const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = process.env.PORT || 4000;
const APP_SECRET = process.env.APP_SECRET || 'not-set';

const server = http.createServer((req, res) => {
  // Handle API routes
  if (req.url.startsWith('/api/')) {
    handleApi(req, res);
    return;
  }

  // Serve public/index.html for root path
  if (req.url === '/' || req.url === '/index.html') {
    serveFile(res, 'public/index.html', 'text/html');
    return;
  }

  // 404 for everything else
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not Found');
});

function handleApi(req, res) {
  if (req.url === '/api/hello') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ ok: true, app: 'pipeline-proof' }));
  } else if (req.url === '/api/secret') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ secret: APP_SECRET }));
  } else {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('API endpoint not found');
  }
}

function serveFile(res, filePath, contentType) {
  const fullPath = path.join(__dirname, filePath);

  fs.readFile(fullPath, (err, data) => {
    if (err) {
      res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end('Internal Server Error');
      return;
    }

    res.writeHead(200, { 'Content-Type': contentType });
    res.end(data);
  });
}

server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

